package com.ksh321.songrecord.api.account;
import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.*;
import org.springframework.transaction.support.TransactionTemplate;
import com.ksh321.songrecord.api.jobs.JobQueue;
import static com.ksh321.songrecord.api.songs.SongQueryKeys.bytes;

/** Durable phases; external I/O runs outside SQL and every effect is lease-fenced. */
public final class AccountDeletionWorker {
 private final JdbcTemplate db;private final JobQueue jobs;private final DeletionObjects objects;private final DeletionArtifacts artifacts;private final Clock clock;private final TransactionTemplate tx;
 public AccountDeletionWorker(JdbcTemplate db,PlatformTransactionManager manager,JobQueue jobs,DeletionObjects objects,DeletionArtifacts artifacts,Clock clock){this.db=db;this.jobs=jobs;this.objects=objects;this.artifacts=artifacts;this.clock=clock;tx=new TransactionTemplate(manager);tx.setIsolationLevel(TransactionDefinition.ISOLATION_READ_COMMITTED);tx.setTimeout(30);}
 public boolean runOnce(){var claimed=jobs.claim(JobQueue.Type.ACCOUNT_DELETE);if(claimed.isEmpty())return false;var lease=claimed.get();
  try{
   var work=inspect(lease);UUID owner=lease.userId();long revision=((Number)work.get("owner_revision")).longValue();Instant accepted=time(work.get("accepted_at")).toInstant(ZoneOffset.UTC);
   fence(lease);artifacts.record(owner,revision,accepted);if(!artifacts.recorded(owner,revision,accepted))throw new IllegalStateException("DELETION_ARCHIVE_UNCONFIRMED");
   if(work.get("service_deleted_at")==null){
    var ready=drain(lease);if(ready.isAfter(now())){var delay=Duration.between(now(),ready).plusMillis(1);jobs.defer(lease,delay.compareTo(Duration.ofDays(1))>0?Duration.ofDays(1):delay);return true;}
    objects.clearOwner(owner,()->fence(lease));fence(lease);
    tx.executeWithoutResult(s->{require(lease);new DeletionDatabase(db).purge(owner,lease.id(),now());require(lease);
     db.update("UPDATE account_deletion_work SET service_deleted_at=?,failure_count=0,last_error=NULL,updated_at=? WHERE preparation_id=?",now(),now(),bytes(lease.aggregateId()));
     db.update("UPDATE account_deletion_status SET state='BACKUP_CLEANUP',service_deleted_at=?,retrying=FALSE WHERE id=?",now(),bytes(lease.aggregateId()));
    });
   }
   fence(lease);boolean absent=artifacts.purgeAndVerifyBackups(owner);fence(lease);
   if(!absent){tx.executeWithoutResult(s->{require(lease);boolean overdue=accepted.plus(Duration.ofDays(7)).isBefore(clock.instant());db.update("UPDATE account_deletion_work SET failure_count=0,last_error=?,updated_at=? WHERE preparation_id=?",overdue?"BACKUP_PURGE_OVERDUE":null,now(),bytes(lease.aggregateId()));db.update("UPDATE account_deletion_status SET retrying=? WHERE id=?",overdue,bytes(lease.aggregateId()));if(overdue)org.slf4j.LoggerFactory.getLogger(getClass()).error("Account deletion backup deadline exceeded; operator recovery required");});jobs.defer(lease,Duration.ofHours(1));return true;}
   if(!jobs.complete(lease,()->{require(lease);db.update("UPDATE account_deletion_work SET backup_confirmed_at=?,failure_count=0,last_error=NULL,updated_at=? WHERE preparation_id=?",now(),now(),bytes(lease.aggregateId()));if(db.update("UPDATE account_deletion_status SET state='COMPLETED',completed_at=?,retrying=FALSE WHERE id=? AND state='BACKUP_CLEANUP' AND service_deleted_at IS NOT NULL",now(),bytes(lease.aggregateId()))!=1)throw new IllegalStateException("DELETION_COMPLETION_UNCONFIRMED");}))throw new IllegalStateException("DELETION_LEASE_LOST");
  }catch(com.ksh321.songrecord.api.operations.BackupDeletionFence.Awaiting pending){jobs.defer(lease,Duration.ofSeconds(5));}catch(Exception e){if(e instanceof InterruptedException)Thread.currentThread().interrupt();try{int failures=tx.execute(s->{require(lease);db.update("UPDATE account_deletion_work SET failure_count=failure_count+1,last_error='DELETE_RESULT_UNCONFIRMED',updated_at=? WHERE preparation_id=?",now(),bytes(lease.aggregateId()));db.update("UPDATE account_deletion_status SET retrying=TRUE WHERE id=? AND state<>'COMPLETED'",bytes(lease.aggregateId()));return db.queryForObject("SELECT failure_count FROM account_deletion_work WHERE preparation_id=?",Integer.class,bytes(lease.aggregateId()));});if(failures>=jobs.retryLimit()){jobs.fail(lease,false);org.slf4j.LoggerFactory.getLogger(getClass()).error("Account deletion retry budget exhausted; operator recovery required");}else jobs.defer(lease,Duration.ofSeconds(Math.min(300,5L<<Math.min(failures-1,6))));}catch(RuntimeException lost){/* A newer lease owns recovery; never advance a stale worker. */}}
  return true;
 }
 private Map<String,Object> inspect(JobQueue.Lease lease){return tx.execute(s->{require(lease);if(lease.userId()==null||!com.ksh321.songrecord.api.idempotency.CanonicalRequest.canonical(lease.payload()).equals("{\"preparation_id\":\""+lease.aggregateId()+"\"}"))throw new IllegalStateException("DELETION_JOB_BINDING_INVALID");var work=db.queryForMap("SELECT * FROM account_deletion_work WHERE preparation_id=? AND owner_id=? FOR UPDATE",bytes(lease.aggregateId()),bytes(lease.userId()));if(db.queryForList("SELECT id FROM deletion_ledger WHERE user_id=? AND entity_type='USER' AND entity_id=? AND revision=?",bytes(lease.userId()),bytes(lease.userId()),work.get("owner_revision")).isEmpty())throw new IllegalStateException("DELETION_LEDGER_UNCONFIRMED");var states=db.queryForList("SELECT state,service_deleted_at FROM account_deletion_status WHERE id=? FOR UPDATE",bytes(lease.aggregateId()));if(states.size()!=1||!Set.of("ACCEPTED","DELETING","BACKUP_CLEANUP").contains(states.getFirst().get("state")))throw new IllegalStateException("DELETION_STATE_INVALID");
  var status=states.getFirst();boolean service=work.get("service_deleted_at")!=null;
  if(service&&(!"BACKUP_CLEANUP".equals(status.get("state"))||status.get("service_deleted_at")==null||!time(work.get("service_deleted_at")).equals(time(status.get("service_deleted_at")))||!new DeletionDatabase(db).purged(lease.userId()))||!service&&"BACKUP_CLEANUP".equals(status.get("state")))throw new IllegalStateException("DELETION_SERVICE_PROOF_UNCONFIRMED");return work;});}
 private LocalDateTime drain(JobQueue.Lease lease){return tx.execute(s->{require(lease);var work=db.queryForMap("SELECT drain_until FROM account_deletion_work WHERE preparation_id=? FOR UPDATE",bytes(lease.aggregateId()));if(work.get("drain_until")!=null)return time(work.get("drain_until"));
  var users=db.queryForList("SELECT status FROM app_user WHERE id=? FOR UPDATE",bytes(lease.userId()));if(users.size()!=1||!"DELETING".equals(users.getFirst().get("status")))throw new IllegalStateException("DELETION_OWNER_AUTHORITY_LOST");
  var ready=now();for(var row:db.queryForList("SELECT lease_until FROM job WHERE user_id=? AND id<>? AND state='RUNNING' FOR UPDATE",bytes(lease.userId()),bytes(lease.id())))if(row.get("lease_until")!=null&&time(row.get("lease_until")).isAfter(ready))ready=time(row.get("lease_until"));
  for(var row:db.queryForList("SELECT expires_at FROM recording_upload WHERE user_id=? FOR UPDATE",bytes(lease.userId())))if(time(row.get("expires_at")).isAfter(ready))ready=time(row.get("expires_at"));
  ready=ready.plusSeconds(120);db.update("UPDATE job SET state='CANCELLED',lease_token=NULL,claimed_at=NULL,lease_until=NULL,finished_at=GREATEST(created_at,?),updated_at=?,revision=revision+1 WHERE user_id=? AND id<>? AND state IN ('QUEUED','RUNNING','RETRY_WAIT')",now(),now(),bytes(lease.userId()),bytes(lease.id()));
  db.update("UPDATE account_deletion_work SET drain_until=?,updated_at=? WHERE preparation_id=?",ready,now(),bytes(lease.aggregateId()));db.update("UPDATE account_deletion_status SET state='DELETING' WHERE id=?",bytes(lease.aggregateId()));return ready;
 });}
 public int retireCompleted(){int count=0;var rows=db.queryForList("SELECT preparation_id,owner_id FROM account_deletion_work WHERE backup_confirmed_at IS NOT NULL AND accepted_at<=? ORDER BY accepted_at LIMIT 100",now().minusDays(30));for(var row:rows){var id=com.ksh321.songrecord.api.songs.SongQueryKeys.uuid((byte[])row.get("preparation_id"));var owner=com.ksh321.songrecord.api.songs.SongQueryKeys.uuid((byte[])row.get("owner_id"));try{artifacts.retire(owner);tx.executeWithoutResult(s->{var work=db.queryForList("SELECT preparation_id FROM account_deletion_work WHERE preparation_id=? AND backup_confirmed_at IS NOT NULL AND accepted_at<=? FOR UPDATE",bytes(id),now().minusDays(30));if(work.isEmpty())throw new IllegalStateException("DELETION_RETENTION_AUTHORITY_LOST");db.update("DELETE FROM account_deletion_status WHERE id=? AND state='COMPLETED' AND expires_at<=?",bytes(id),now());db.update("DELETE FROM account_deletion_device_proof WHERE owner_id=?",bytes(owner));db.update("DELETE FROM deletion_ledger WHERE user_id=?",bytes(owner));db.update("DELETE FROM job WHERE user_id=?",bytes(owner));db.update("DELETE FROM account_deletion_work WHERE preparation_id=?",bytes(id));});count++;}catch(Exception unavailable){org.slf4j.LoggerFactory.getLogger(getClass()).error("Deletion archive retention needs operator recovery");}}return count;}
 private void fence(JobQueue.Lease lease){if(!jobs.renew(lease))throw new IllegalStateException("DELETION_LEASE_LOST");}
 private void require(JobQueue.Lease lease){if(db.queryForList("SELECT id FROM job WHERE id=? AND type='ACCOUNT_DELETE' AND user_id=? AND aggregate_id=? AND state='RUNNING' AND lease_token=? AND lease_until>?",bytes(lease.id()),bytes(lease.userId()),bytes(lease.aggregateId()),bytes(lease.token()),now()).isEmpty())throw new IllegalStateException("DELETION_LEASE_LOST");}
 private LocalDateTime now(){return LocalDateTime.ofInstant(clock.instant(),ZoneOffset.UTC).truncatedTo(java.time.temporal.ChronoUnit.MILLIS);}
 private static LocalDateTime time(Object v){return v instanceof java.sql.Timestamp t?t.toLocalDateTime():(LocalDateTime)v;}
}
